package registry

// Account 是账户登记信息。停用后仍可查询其原有藏品与历史。
type Account struct {
	ID       string // 唯一编号
	Metadata string // 文字元数据，可为空
	Active   bool   // 是否可用；停用后不能发行、发起或接收新的转让
}

// Series 是系列信息。仅创建账户可以发行藏品或封存系列。
type Series struct {
	ID        string // 系列编号
	CreatorID string // 创建账户编号
	Metadata  string // 文字元数据
	Sealed    bool   // 是否已封存；封存不可撤销
}

// Item 是单件藏品的静态登记信息。
type Item struct {
	ID         string // 唯一藏品编号，同一编号不能产生第二件藏品
	SeriesID   string // 所属系列
	BatchNo    string // 批次号
	Metadata   string // 文字元数据
	IssuedTxID int64  // 发行记录在历史中的序号
}

// Holding 是一件藏品的当前持有状态。
type Holding struct {
	ItemID  string // 藏品编号
	OwnerID string // 当前持有人
	Version int64  // 当前持有版本：发行后为 1，每次成功转让加 1
}

// HistoryEntry 是一条发行或成功转让记录，按发生先后排列。
type HistoryEntry struct {
	Seq       int64  // 严格递增的记录序号，也即发生顺序
	Kind      string // "issue" 或 "transfer"
	ItemID    string // 藏品编号
	Operator  string // 操作者账户编号
	Reason    string // 操作原因
	RequestID string // 请求号
	// FromID 是转让前持有人；发行前为空。
	FromID string
	// ToID 是转让后持有人（发行时为初始持有人）。
	ToID string
	// FromVersion 是转让前持有版本；发行前为 0（语义上为空）。
	FromVersion int64
	// ToVersion 是转让后持有版本（发行后为 1）。
	ToVersion int64
}

// IssueRequest 是发行请求的业务参数（幂等判定以此为准）。
type IssueRequest struct {
	Operator  string // 操作者，必须是系列创建账户且可用
	Reason    string // 原因
	RequestID string // 请求号，同一操作者在发行与转让之间共用
	ItemID    string // 唯一藏品编号
	SeriesID  string // 所属系列
	BatchNo   string // 批次号
	Metadata  string // 藏品文字元数据
	HolderID  string // 初始持有人，必须是已登记且可用的账户
}

// TransferRequest 是转让请求的业务参数。
type TransferRequest struct {
	Operator      string // 操作者，必须是当前持有人且可用
	Reason        string // 原因
	RequestID     string // 请求号
	ItemID        string // 藏品编号
	ExpectedOwner string // 期望当前持有人（通常即发起人）
	ExpectedVer   int64  // 期望当前持有版本
	ToID          string // 接收人，必须已登记、可用且不同于当前持有人
}

// IssueResult 是发行请求的处理结果。
type IssueResult struct {
	ItemID   string // 藏品编号
	OwnerID  string // 初始持有人
	Version  int64  // 持有版本，恒为 1
	TxSeq    int64  // 发行历史序号
	Replayed bool   // 是否为重复提交回放的首次结果
	Err      error  // 首次或本次的业务拒绝；成功时为 nil
}

// TransferResult 是转让请求的处理结果。
type TransferResult struct {
	ItemID   string // 藏品编号
	FromID   string // 转让前持有人
	ToID     string // 转让后持有人
	Version  int64  // 转让后版本
	TxSeq    int64  // 转让历史序号
	Replayed bool   // 是否为重复提交回放的首次结果
	Err      error  // 业务拒绝；成功时为 nil
}

package registry

import "errors"

// 错误哨兵。业务拒绝与参数错误使用包裹这些哨兵的错误，调用方可用
// errors.Is 判定；返回结果中的 Err 字段同样包裹这些哨兵。
var (
	// ErrNotFound 表示查询或引用的账户、系列或藏品不存在。
	ErrNotFound = errors.New("registry: 对象不存在")

	// ErrAlreadyExists 表示账户、系列或藏品编号已被占用。
	ErrAlreadyExists = errors.New("registry: 对象已存在")

	// ErrAccountInactive 表示账户已停用，不能参与新的发行或转让。
	ErrAccountInactive = errors.New("registry: 账户已停用")

	// ErrSeriesSealed 表示系列已封存，不能继续发行；封存不可撤销。
	ErrSeriesSealed = errors.New("registry: 系列已封存")

	// ErrConflict 表示乐观并发冲突：藏品持有人或期望版本与当前状态不符。
	ErrConflict = errors.New("registry: 持有人或版本不符，转让被拒绝")

	// ErrSameAccount 表示转让的发起人与接收人相同。
	ErrSameAccount = errors.New("registry: 转让发起人与接收人不能相同")

	// ErrForbidden 表示操作者无权执行该操作（例如非系列创建账户发行或封存）。
	ErrForbidden = errors.New("registry: 操作者无权执行该操作")

	// ErrRequestConflict 表示请求号已被同一操作者使用，但本次业务参数不同。
	ErrRequestConflict = errors.New("registry: 请求号冲突")

	// ErrInvalidArgument 表示必填内容缺失或参数不合法。
	ErrInvalidArgument = errors.New("registry: 参数不合法")

	// ErrCorrupt 表示登记册数据已存在但无法读取或解析。
	ErrCorrupt = errors.New("registry: 登记册数据无法读取")

	// ErrLocked 表示登记册正被另一个进程以独占方式使用。
	ErrLocked = errors.New("registry: 登记册已被占用")
)

// Package registry 是本地数字藏品登记与流转的实现。
//
// 一个 Registry 对应本机上的一个数据目录：用 Create 新建登记册，用 Open
// 打开已有登记册。账户、系列、藏品、持有关系、历史与请求结果在每次成功
// 操作返回前原子落盘，正常关闭或进程被直接终止后重开都能完整保留；已有
// 数据无法读取时 Open 会明确报错，不会被当成空登记册。
package registry

// Ready 表示基线可以运行。新增能力不改变其语义。
func Ready() bool { return true }

