20	// snapshot 是登记册的全量落盘结构。账户、系列、藏品、持有、历史与
21	// 请求结果都在同一个快照中，一次操作一次原子替换，保证"藏品已换人
22	// 就一定有对应历史"。
23	type snapshot struct {
24		Version  int                `json:"version"`
25		Accounts map[string]account `json:"accounts"`
26		Series   map[string]series  `json:"series"`
27		Items    map[string]item    `json:"items"`
