29		History  []historyEntry     `json:"history"`
30		Requests map[string]request `json:"requests"`
31		NextSeq  int64              `json:"next_seq"`
32	}
33	
34	type account struct {
35		ID       string `json:"id"`
36		Metadata string `json:"metadata"`
37		Active   bool   `json:"active"`
38	}
39	
40	type series struct {
41		ID        string `json:"id"`
42		CreatorID string `json:"creator_id"`
43		Metadata  string `json:"metadata"`
44		Sealed    bool   `json:"sealed"`
45	}
46	
47	type item struct {
48		ID         string `json:"id"`
49		SeriesID   string `json:"series_id"`
50		BatchNo    string `json:"batch_no"`
51		Metadata   string `json:"metadata"`
52		IssuedTxID int64  `json:"issued_tx_id"`
53	}
54	
55	type holding struct {
56		ItemID  string `json:"item_id"`
57		OwnerID string `json:"owner_id"`
58		Version int64  `json:"version"`
59	}
60	
61	type historyEntry struct {
62		Seq         int64  `json:"seq"`
63		Kind        string `json:"kind"`
64		ItemID      string `json:"item_id"`
65		Operator    string `json:"operator"`
66		Reason      string `json:"reason"`
67		RequestID   string `json:"request_id"`
68		FromID      string `json:"from_id"`
69		ToID        string `json:"to_id"`
70		FromVersion int64  `json:"from_version"`
71		ToVersion   int64  `json:"to_version"`
72	}
73	
74	// request 保存每个 (操作者, 请求号) 的首次结果，用于幂等回放。
75	// 同一操作者的请求号在发行与转让两类操作间共用。
76	type request struct {
77		Operator  string `json:"operator"`
78		RequestID string `json:"request_id"`
79		Kind      string `json:"kind"` // "issue" / "transfer"
80		// 规范化后的业务参数签名。签名一致才回放；不一致报请求号冲突。
81		Params string `json:"params"`
82		// 业务拒绝也落盘：相同参数重提返回首次的拒绝。
83		Rejected bool   `json:"rejected"`
84		Reason   string `json:"reject_reason"` // 哨兵错误对应的稳定标识
85		// 成功结果。
86		ItemID  string `json:"item_id,omitempty"`
87		FromID  string `json:"from_id,omitempty"`
88		ToID    string `json:"to_id,omitempty"`
89		Version int64  `json:"version,omitempty"`
90		TxSeq   int64  `json:"tx_seq,omitempty"`
91	}
92	
93	func newSnapshot() *snapshot {
94		return &snapshot{
95			Version:  stateVersion,
96			Accounts: make(map[string]account),
97			Series:   make(map[string]series),
98			Items:    make(map[string]item),
99			Holdings: make(map[string]holding),
100			Requests: make(map[string]request),
101		}
102	}
103	
104	func (s *snapshot) validate() error {
105		if s.Version != stateVersion {
106			return fmt.Errorf("%w: 不支持的快照版本 %d", ErrCorrupt, s.Version)
107		}
108		if s.Accounts == nil || s.Series == nil || s.Items == nil ||
109			s.Holdings == nil || s.Requests == nil {
110			return fmt.Errorf("%w: 快照内容不完整", ErrCorrupt)
111		}
112		if s.NextSeq < int64(len(s.History)) {
113			return fmt.Errorf("%w: 历史序号不连续", ErrCorrupt)
114		}
115		return nil
116	}
117	
118	// store 负责一个登记册目录的加锁、读取与原子写入。
119	type store struct {
120		dir  string
121		lock *os.File // 跨进程 flock
122	}
123	
124	func dataFile(dir string) string { return filepath.Join(dir, "registry.json") }
125	func lockFile(dir string) string { return filepath.Join(dir, "registry.lock") }
126	func tempFile(dir string) string { return filepath.Join(dir, ".registry.json.tmp") }
127	
128	// acquireLock 在登记册目录中以非阻塞方式取独占 flock。
129	func acquireLock(dir string) (*os.File, error) {
130		f, err := os.OpenFile(lockFile(dir), os.O_CREATE|os.O_RDWR, fileMode)
131		if err != nil {
132			return nil, fmt.Errorf("registry: 无法打开锁文件: %w", err)
133		}
134		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
