func (r *Registry) replayTransfer(prev request, sig string) (TransferResult, error) {
	if prev.Kind != "transfer" || prev.Params != sig {
		return TransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
