// ---- 限时一次性代转授权 ----

// authzCurrentStatus 计算授权当前状态。撤销与使用是落盘的终态；到期不
// 落盘，按当前时间实时判断——从到期时间点起即视为已过期。
func authzCurrentStatus(a authzRec, now time.Time) string {
	switch a.Status {
	case "revoked":
		return AuthRevoked
	case "used":
		return AuthUsed
	}
	if !a.ExpiresAt.IsZero() && !now.Before(a.ExpiresAt) {
		return AuthExpired
	}
	return AuthActive
}

func (req CreateAuthorizationRequest) validatePresent() error {
	missing := []string{}
	if strings.TrimSpace(req.Operator) == "" {
		missing = append(missing, "operator")
	}
	if strings.TrimSpace(req.Reason) == "" {
		missing = append(missing, "reason")
	}
	if strings.TrimSpace(req.RequestID) == "" {
		missing = append(missing, "request_id")
	}
	if strings.TrimSpace(req.AuthID) == "" {
		missing = append(missing, "auth_id")
	}
	if strings.TrimSpace(req.ItemID) == "" {
		missing = append(missing, "item_id")
	}
	if strings.TrimSpace(req.TrusteeID) == "" {
		missing = append(missing, "trustee_id")
	}
	if strings.TrimSpace(req.ToID) == "" {
		missing = append(missing, "to_id")
	}
	if strings.TrimSpace(req.ExpectedOwner) == "" {
		missing = append(missing, "expected_owner")
	}
	if req.ExpectedVer <= 0 {
		missing = append(missing, "expected_version")
	}
	if req.ExpiresAt.IsZero() {
		missing = append(missing, "expires_at")
	}
	if len(missing) > 0 {
		return fmt.Errorf("%w: 创建授权请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
	}
	return nil
}

func createAuthzParamsSig(req CreateAuthorizationRequest) string {
	b, _ := json.Marshal(struct {
		Kind          string `json:"kind"`
		AuthID        string `json:"auth_id"`
		ItemID        string `json:"item_id"`
		TrusteeID     string `json:"trustee_id"`
		ToID          string `json:"to_id"`
		ExpectedOwner string `json:"expected_owner"`
		ExpectedVer   int64  `json:"expected_version"`
		ExpiresAt     string `json:"expires_at"`
		Reason        string `json:"reason"`
	}{"auth_create", req.AuthID, req.ItemID, req.TrusteeID, req.ToID,
		req.ExpectedOwner, req.ExpectedVer,
		req.ExpiresAt.UTC().Format(time.RFC3339Nano), req.Reason})
	return string(b)
}

// CreateAuthorization 由当前持有人为一件已发行藏品创建限时、一次性的
// 代转授权：指定唯一授权编号、受托账户、固定接收账户、绝对到期时间，
// 以及期望持有人与期望版本。授权绑定创建时的持有版本，不改变持有关系，
// 也不限制持有人继续直接转让。受托人不能是授权人；受托人可与接收人
// 相同，但接收人也不能是授权人。到期时间必须晚于当前时间。
//
// 请求号与发行、转让共用同一操作者的请求号范围：相同业务参数重提返回
// 首次结果（成功或状态类业务拒绝），参数变化返回 ErrRequestConflict；
// 参数错误与引用不存在不占用请求号。
func (r *Registry) CreateAuthorization(req CreateAuthorizationRequest) (CreateAuthorizationResult, error) {
	if err := req.validatePresent(); err != nil {
		return CreateAuthorizationResult{}, err
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return CreateAuthorizationResult{}, err
	}

	now := r.now()
	key := requestKey(req.Operator, req.RequestID)
	sig := createAuthzParamsSig(req)
	if prev, ok := r.state.Requests[key]; ok {
		return r.replayCreateAuthz(prev, sig)
	}

	if bizErr := r.checkCreateAuthorization(req, now); bizErr != nil {
		if !isValidationErr(bizErr) {
			// 状态类业务拒绝（编号占用、停用、同人、版本不符、到期时间
			// 已过等）占用请求号并落盘；参数错误与引用不存在不占用。
			r.state.Requests[key] = request{
				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
				Params: sig, Rejected: true, Reason: errCode(bizErr),
				AuthID: req.AuthID, ItemID: req.ItemID,
			}
			_ = r.commit()
		}
		return CreateAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
	}

	h := r.state.Holdings[req.ItemID]
	a := authzRec{
		ID: req.AuthID, ItemID: req.ItemID, GranterID: req.Operator,
		TrusteeID: req.TrusteeID, ToID: req.ToID, ExpiresAt: req.ExpiresAt,
		GrantVer: h.Version, CreatedAt: now,
	}
	r.state.Authzs[req.AuthID] = a
	authSeq := r.state.NextAuthSeq + 1
	r.state.NextAuthSeq = authSeq
	r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
		Seq: authSeq, AuthID: req.AuthID, ItemID: req.ItemID, Kind: "create",
		Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
		FromStatus: "", ToStatus: AuthActive, OccurredAt: now,
	})
	r.state.Requests[key] = request{
		Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
		Params: sig, AuthID: req.AuthID, ItemID: req.ItemID, Version: h.Version,
	}
	if err := r.commit(); err != nil {
		return CreateAuthorizationResult{}, err
	}
	return CreateAuthorizationResult{AuthID: req.AuthID, Status: AuthActive, GrantVer: h.Version}, nil
}

func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
	h, ok := r.state.Holdings[req.ItemID]
	if !ok {
		if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
			return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
		}
		return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
	}
	op, ok := r.state.Accounts[req.Operator]
	if !ok {
		return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
	}
	trustee, ok := r.state.Accounts[req.TrusteeID]
	if !ok {
		return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
	}
	to, ok := r.state.Accounts[req.ToID]
	if !ok {
		return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
	}
	if req.TrusteeID == req.Operator {
		return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
	}
	if req.ToID == req.Operator {
		return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
	}
	if !op.Active {
		return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
	}
	if !trustee.Active {
		return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
	}
	if !to.Active {
		return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
	}
	// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
	if !req.ExpiresAt.After(now) {
		return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
			ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
	}
	if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
		req.Operator != h.OwnerID {
		return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
			ErrConflict, req.ItemID, h.OwnerID, h.Version)
	}
	if _, exists := r.state.Authzs[req.AuthID]; exists {
		return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
	}
	return nil
}

func (r *Registry) replayCreateAuthz(prev request, sig string) (CreateAuthorizationResult, error) {
	if prev.Kind != "auth_create" || prev.Params != sig {
		return CreateAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
			ErrRequestConflict, prev.Operator, prev.RequestID)
	}
	res := CreateAuthorizationResult{AuthID: prev.AuthID, GrantVer: prev.Version,
		Status: AuthActive, Replayed: true}
	if prev.Rejected {
		res.Err = codeErr(prev.Reason)
		return res, res.Err
	}
	return res, nil
}

func revokeAuthzParamsSig(req RevokeAuthorizationRequest) string {
	b, _ := json.Marshal(struct {
		Kind   string `json:"kind"`
		AuthID string `json:"auth_id"`
		Reason string `json:"reason"`
	}{"auth_revoke", req.AuthID, req.Reason})
	return string(b)
}

// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销；
// 已使用的授权不能撤销（返回 ErrAuthorizationUsed）。授权已撤销时再次
// 撤销不新增授权变更记录，按成功返回。请求号语义与其他操作一致。
func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
	missing := []string{}
	if strings.TrimSpace(req.Operator) == "" {
		missing = append(missing, "operator")
	}
	if strings.TrimSpace(req.Reason) == "" {
		missing = append(missing, "reason")
	}
	if strings.TrimSpace(req.RequestID) == "" {
		missing = append(missing, "request_id")
	}
	if strings.TrimSpace(req.AuthID) == "" {
		missing = append(missing, "auth_id")
	}
	if len(missing) > 0 {
		return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
			ErrInvalidArgument, strings.Join(missing, ", "))
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return RevokeAuthorizationResult{}, err
	}

	now := r.now()
	key := requestKey(req.Operator, req.RequestID)
	sig := revokeAuthzParamsSig(req)
	if prev, ok := r.state.Requests[key]; ok {
		return r.replayRevokeAuthz(prev, sig)
	}

	a, ok := r.state.Authzs[req.AuthID]
	if !ok {
		// 引用不存在不占用请求号。
		err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
		return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
	}
	if a.GranterID != req.Operator {
		bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
			ErrForbidden, a.GranterID, req.AuthID)
		r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
		return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
	}
	switch authzCurrentStatus(a, now) {
	case AuthUsed:
		bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
		r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
		return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
	case AuthRevoked:
		// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
		// 相同请求重放回放同一结果。
		r.state.Requests[key] = request{
			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
			Params: sig, AuthID: req.AuthID,
		}
		if err := r.commit(); err != nil {
			return RevokeAuthorizationResult{}, err
		}
		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
	}

	from := AuthActive
	if authzCurrentStatus(a, now) == AuthExpired {
		from = AuthExpired
	}
	a.Status = "revoked"
	a.RevokedAt = now
	r.state.Authzs[req.AuthID] = a
	authSeq := r.state.NextAuthSeq + 1
	r.state.NextAuthSeq = authSeq
	r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
		Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
		Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
		FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
	})
	r.state.Requests[key] = request{
		Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
		Params: sig, AuthID: req.AuthID,
	}
	if err := r.commit(); err != nil {
		return RevokeAuthorizationResult{}, err
	}
	return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
}

// recordAuthzRequest 记录授权类操作的状态类业务拒绝并尽力落盘。
func (r *Registry) recordAuthzRequest(key, sig string, req RevokeAuthorizationRequest, kind string, bizErr error) {
	r.state.Requests[key] = request{
		Operator: req.Operator, RequestID: req.RequestID, Kind: kind,
		Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
	}
	_ = r.commit()
}

func (r *Registry) replayRevokeAuthz(prev request, sig string) (RevokeAuthorizationResult, error) {
	if prev.Kind != "auth_revoke" || prev.Params != sig {
		return RevokeAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
			ErrRequestConflict, prev.Operator, prev.RequestID)
	}
	res := RevokeAuthorizationResult{AuthID: prev.AuthID, Status: AuthRevoked, Replayed: true}
	if prev.Rejected {
		res.Err = codeErr(prev.Reason)
		res.Status = ""
		return res, res.Err
	}
	return res, nil
}

func proxyTransferParamsSig(req ProxyTransferRequest) string {
	b, _ := json.Marshal(struct {
		Kind   string `json:"kind"`
		AuthID string `json:"auth_id"`
		Reason string `json:"reason"`
	}{"proxy_transfer", req.AuthID, req.Reason})
	return string(b)
}

// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
// 操作者记为实际受托账户并可通过授权编号追溯。
//
// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
// 账户已停用或藏品再次易手，仍返回首次的转让结果。
func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
	missing := []string{}
	if strings.TrimSpace(req.Operator) == "" {
		missing = append(missing, "operator")
	}
	if strings.TrimSpace(req.Reason) == "" {
		missing = append(missing, "reason")
	}
	if strings.TrimSpace(req.RequestID) == "" {
		missing = append(missing, "request_id")
	}
	if strings.TrimSpace(req.AuthID) == "" {
		missing = append(missing, "auth_id")
	}
	if len(missing) > 0 {
		return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
			ErrInvalidArgument, strings.Join(missing, ", "))
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return ProxyTransferResult{}, err
	}

	now := r.now()
	key := requestKey(req.Operator, req.RequestID)
	sig := proxyTransferParamsSig(req)
	if prev, ok := r.state.Requests[key]; ok {
		return r.replayProxyTransfer(prev, sig)
	}

	if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
		if !isValidationErr(bizErr) {
			r.state.Requests[key] = request{
				Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
				Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
			}
			_ = r.commit()
		}
		return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
	}

	a := r.state.Authzs[req.AuthID]
	h := r.state.Holdings[a.ItemID]
	seq := r.state.NextSeq + 1
	r.state.NextSeq = seq
	from := h.OwnerID
	fromVer := h.Version
	h.OwnerID = a.ToID
	h.Version = fromVer + 1
	r.state.Holdings[a.ItemID] = h
	r.state.History = append(r.state.History, historyEntry{
		Seq: seq, Kind: "transfer", ItemID: a.ItemID, Operator: req.Operator,
		Reason: req.Reason, RequestID: req.RequestID,
		FromID: from, ToID: a.ToID, FromVersion: fromVer, ToVersion: fromVer + 1,
		AuthID: a.ID,
	})
	a.Status = "used"
	a.UsedTxSeq = seq
	a.UsedAt = now
	r.state.Authzs[a.ID] = a
	authSeq := r.state.NextAuthSeq + 1
	r.state.NextAuthSeq = authSeq
	r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
		Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
		Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
		FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: seq, OccurredAt: now,
	})
	r.state.Requests[key] = request{
		Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
		Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: from, ToID: a.ToID,
		Version: fromVer + 1, TxSeq: seq,
	}
	if err := r.commit(); err != nil {
		return ProxyTransferResult{}, err
	}
	return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: from,
		ToID: a.ToID, Version: fromVer + 1, TxSeq: seq}, nil
}

func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
	a, ok := r.state.Authzs[req.AuthID]
	if !ok {
		return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
	}
	op, ok := r.state.Accounts[req.Operator]
	if !ok {
		return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
	}
	granter, gOk := r.state.Accounts[a.GranterID]
	to, tOk := r.state.Accounts[a.ToID]
	if req.Operator != a.TrusteeID {
		return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
			ErrForbidden, req.Operator, req.AuthID)
	}
	if !gOk {
		return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
	}
	if !tOk {
		return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
	}
	if !op.Active {
		return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
	}
	if !granter.Active {
		return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
	}
	if !to.Active {
		return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
	}
	switch authzCurrentStatus(a, now) {
	case AuthRevoked:
		return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
	case AuthExpired:
		return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
	case AuthUsed:
		return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
	}
	// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
	// 授权人手中也不会回到旧版本，旧授权据此永久失效。
	h, ok := r.state.Holdings[a.ItemID]
	if !ok {
		return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
	}
	if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
		return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
			ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
	}
	return nil
}

func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
	if prev.Kind != "proxy_transfer" || prev.Params != sig {
		return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
			ErrRequestConflict, prev.Operator, prev.RequestID)
	}
	res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
		ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
	if prev.Rejected {
		res.Err = codeErr(prev.Reason)
		return res, res.Err
	}
	return res, nil
}

// ---- 授权查询 ----

// GetAuthorization 按编号查询授权内容与撤销、使用状态。授权不存在时
// 返回包裹 ErrNotFound 的错误；返回的 Status 按当前时间实时计算，
// 到期但尚未终结的授权返回 AuthExpired。
func (r *Registry) GetAuthorization(authID string) (Authorization, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return Authorization{}, err
	}
	a, ok := r.state.Authzs[authID]
	if !ok {
		return Authorization{}, fmt.Errorf("%w: 授权 %s", ErrNotFound, authID)
	}
	return Authorization{
		ID: a.ID, ItemID: a.ItemID, GranterID: a.GranterID, TrusteeID: a.TrusteeID,
		ToID: a.ToID, ExpiresAt: a.ExpiresAt, GrantVer: a.GrantVer,
		Status:    authzCurrentStatus(a, r.now()),
		UsedTxSeq: a.UsedTxSeq, UsedAt: a.UsedAt, CreatedAt: a.CreatedAt,
		RevokedAt: a.RevokedAt,
	}, nil
}

// AuthorizationHistory 按藏品查看授权变更记录（创建、撤销、使用），
// 按发生先后排列；每条记录包含操作者、原因、请求号与前后状态。藏品
// 不存在时返回包裹 ErrNotFound 的错误。
func (r *Registry) AuthorizationHistory(itemID string) ([]AuthorizationEvent, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return nil, err
	}
	if _, ok := r.state.Items[itemID]; !ok {
		return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
	}
	out := make([]AuthorizationEvent, 0)
	for _, e := range r.state.AuthEvents {
		if e.ItemID != itemID {
			continue
		}
		out = append(out, AuthorizationEvent{
			Seq: e.Seq, AuthID: e.AuthID, ItemID: e.ItemID, Kind: e.Kind,
			Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
			FromStatus: e.FromStatus, ToStatus: e.ToStatus, TxSeq: e.TxSeq,
			OccurredAt: e.OccurredAt,
		})
	}
	return out, nil
}

// ---- 查询 ----

input.content:
package registry

import (
	"errors"
	"fmt"
	"path/filepath"
	"sync"
	"testing"
	"time"
)

// authzWorld 建立 alice（持有人/创作者）、bob（受托人）、carol（接收人）
// 三个可用账户，并向 alice 发行藏品 i1（持有版本 1）。
func authzWorld(t *testing.T, r *Registry) {
	t.Helper()
	setupWorld(t, r)
	if err := r.RegisterAccount("carol", "接收人"); err != nil {
		t.Fatal(err)
	}
	if _, err := r.Issue(issueReq("i1", "alice")); err != nil {
		t.Fatal(err)
	}
}

func createAuthReq(r *Registry, authID string, expiry time.Duration) CreateAuthorizationRequest {
	return CreateAuthorizationRequest{
		Operator: "alice", Reason: "委托代转", RequestID: "create-" + authID,
		AuthID: authID, ItemID: "i1", TrusteeID: "bob", ToID: "carol",
		ExpectedOwner: "alice", ExpectedVer: 1,
		ExpiresAt: r.now().Add(expiry),
	}
}

func proxyReq(op, authID, rid string) ProxyTransferRequest {
	return ProxyTransferRequest{Operator: op, Reason: "受托执行", RequestID: rid, AuthID: authID}
}

// ---- 创建授权 ----

func TestCreateAuthorization(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)

	res, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour))
	if err != nil {
		t.Fatalf("CreateAuthorization: %v", err)
	}
	if res.Status != AuthActive || res.GrantVer != 1 || res.Replayed {
		t.Fatalf("unexpected create result: %+v", res)
	}
	a, err := r.GetAuthorization("a1")
	if err != nil {
		t.Fatal(err)
	}
	if a.GranterID != "alice" || a.TrusteeID != "bob" || a.ToID != "carol" ||
		a.GrantVer != 1 || a.ItemID != "i1" || a.Status != AuthActive {
		t.Fatalf("authorization content wrong: %+v", a)
	}
	// 授权不改变持有关系
	h, _ := r.GetHolding("i1")
	if h.OwnerID != "alice" || h.Version != 1 {
		t.Fatalf("creating auth must not change holding: %+v", h)
	}
	// 创建事件
	evs, err := r.AuthorizationHistory("i1")
	if err != nil || len(evs) != 1 {
		t.Fatalf("auth history: %v %v", evs, err)
	}
	if e := evs[0]; e.Kind != "create" || e.Operator != "alice" ||
		e.Reason != "委托代转" || e.RequestID != "create-a1" ||
		e.FromStatus != "" || e.ToStatus != AuthActive {
		t.Fatalf("create event wrong: %+v", e)
	}
	// 藏品历史中不出现授权创建
	hist, _ := r.History("i1")
	if len(hist) != 1 {
		t.Fatalf("create auth must not add item history: %d", len(hist))
	}
}

func TestMultipleAuthorizationsBoundToVersions(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)

	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}
	// 持有人继续直接转让不被授权限制
	if _, err := r.Transfer(xferReq("alice", "i1", "bob", 1, "direct-1")); err != nil {
		t.Fatalf("direct transfer must still work: %v", err)
	}
	// 第二份授权绑定新版本
	r2req := CreateAuthorizationRequest{
		Operator: "bob", Reason: "再次委托", RequestID: "create-a2",
		AuthID: "a2", ItemID: "i1", TrusteeID: "alice", ToID: "carol",
		ExpectedOwner: "bob", ExpectedVer: 2, ExpiresAt: r.now().Add(time.Hour),
	}
	if _, err := r.CreateAuthorization(r2req); err != nil {
		t.Fatalf("second auth: %v", err)
	}
	a1, _ := r.GetAuthorization("a1")
	a2, _ := r.GetAuthorization("a2")
	if a1.GrantVer != 1 || a2.GrantVer != 2 || a1.GranterID != "alice" || a2.GranterID != "bob" {
		t.Fatalf("auths bound to different versions: %+v %+v", a1, a2)
	}
	evs, _ := r.AuthorizationHistory("i1")
	if len(evs) != 2 {
		t.Fatalf("want 2 auth events, got %d", len(evs))
	}
}

func TestCreateAuthorizationValidation(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)

	// 受托人或接收人是授权人 -> 同账户错误
	req := createAuthReq(r, "a1", time.Hour)
	req.TrusteeID = "alice"
	if _, err := r.CreateAuthorization(req); !errors.Is(err, ErrSameAccount) {
		t.Fatalf("trustee==granter must be same-account, got %v", err)
	}
	req = createAuthReq(r, "a1", time.Hour)
	req.ToID = "alice"
	if _, err := r.CreateAuthorization(req); !errors.Is(err, ErrSameAccount) {
		t.Fatalf("to==granter must be same-account, got %v", err)
	}
	// 受托人与接收人可以相同
	req = createAuthReq(r, "a1", time.Hour)
	req.TrusteeID = "carol"
	if _, err := r.CreateAuthorization(req); err != nil {
		t.Fatalf("trustee may equal receiver: %v", err)
	}
	// 到期时间不晚于当前时间 -> 参数错误
	req = createAuthReq(r, "a2", 0)
	if _, err := r.CreateAuthorization(req); !errors.Is(err, ErrInvalidArgument) {
		t.Fatalf("expires==now must be invalid, got %v", err)
	}
	req = createAuthReq(r, "a2", -time.Minute)
	if _, err := r.CreateAuthorization(req); !errors.Is(err, ErrInvalidArgument) {
		t.Fatalf("past expiry must be invalid, got %v", err)
	}
	// 缺字段
	req = createAuthReq(r, "a2", time.Hour)
	req.Reason = " "
	if _, err := r.CreateAuthorization(req); !errors.Is(err, ErrInvalidArgument) {
		t.Fatalf("blank reason: %v", err)
	}
}

func TestCreateAuthorizationBusinessErrors(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)

	// 引用不存在 -> ErrNotFound 且不占用请求号
	req := createAuthReq(r, "a1", time.Hour)
	req.ItemID = "ghost"
	if _, err := r.CreateAuthorization(req); !errors.Is(err, ErrNotFound) {
		t.Fatalf("missing item: %v", err)
	}
	req = createAuthReq(r, "a1", time.Hour)
	req.TrusteeID = "ghost"
	if _, err := r.CreateAuthorization(req); !errors.Is(err, ErrNotFound) {
		t.Fatalf("missing trustee: %v", err)
	}
	// 授权编号已占用
	if _, err := r.CreateAuthorization(createAuthReq(r, "dup", time.Hour)); err != nil {
		t.Fatal(err)
	}
	if _, err := r.CreateAuthorization(createAuthReq(r, "dup", time.Hour)); !errors.Is(err, ErrAlreadyExists) {
		t.Fatalf("duplicate auth id: %v", err)
	}
	// 账户停用
	if err := r.DeactivateAccount("bob"); err != nil {
		t.Fatal(err)
	}
	if _, err := r.CreateAuthorization(createAuthReq(r, "a2", time.Hour)); !errors.Is(err, ErrAccountInactive) {
		t.Fatalf("inactive trustee: %v", err)
	}
	// 持有人或版本不符
	req = createAuthReq(r, "a3", time.Hour)
	req.ExpectedVer = 9
	if _, err := r.CreateAuthorization(req); !errors.Is(err, ErrConflict) {
		t.Fatalf("wrong version: %v", err)
	}
	req = createAuthReq(r, "a3", time.Hour)
	req.Operator = "carol"
	req.ExpectedOwner = "carol"
	if _, err := r.CreateAuthorization(req); !errors.Is(err, ErrConflict) {
		t.Fatalf("non-holder granter: %v", err)
	}
}

// ---- 代转 ----

func TestProxyTransferSuccess(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}

	res, err := r.ProxyTransfer(proxyReq("bob", "a1", "p1"))
	if err != nil {
		t.Fatalf("ProxyTransfer: %v", err)
	}
	if res.FromID != "alice" || res.ToID != "carol" || res.Version != 2 ||
		res.TxSeq != 2 || res.AuthID != "a1" || res.Replayed {
		t.Fatalf("proxy result wrong: %+v", res)
	}
	h, _ := r.GetHolding("i1")
	if h.OwnerID != "carol" || h.Version != 2 {
		t.Fatalf("holding after proxy wrong: %+v", h)
	}
	a, _ := r.GetAuthorization("a1")
	if a.Status != AuthUsed || a.UsedTxSeq != 2 {
		t.Fatalf("auth should be used: %+v", a)
	}
	// 代转出现在藏品历史中：实际操作者是受托人，可追溯授权
	hist, _ := r.History("i1")
	if len(hist) != 2 {
		t.Fatalf("proxy must appear in item history: %d", len(hist))
	}
	if e := hist[1]; e.Kind != "transfer" || e.Operator != "bob" ||
		e.FromID != "alice" || e.ToID != "carol" || e.FromVersion != 1 ||
		e.ToVersion != 2 || e.AuthID != "a1" {
		t.Fatalf("proxy history entry wrong: %+v", e)
	}
	// 授权变更记录中出现使用事件
	evs, _ := r.AuthorizationHistory("i1")
	if len(evs) != 2 || evs[1].Kind != "use" || evs[1].Operator != "bob" ||
		evs[1].FromStatus != AuthActive || evs[1].ToStatus != AuthUsed ||
		evs[1].TxSeq != 2 || evs[1].RequestID != "p1" {
		t.Fatalf("use event wrong: %+v", evs)
	}
}

func TestProxyTransferRejections(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	r.RegisterAccount("dave", "")
	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}

	// 非受托人
	if _, err := r.ProxyTransfer(proxyReq("dave", "a1", "x1")); !errors.Is(err, ErrForbidden) {
		t.Fatalf("non-trustee must be forbidden, got %v", err)
	}
	// 授权不存在 -> ErrNotFound（不占用请求号）
	if _, err := r.ProxyTransfer(proxyReq("bob", "ghost", "x2")); !errors.Is(err, ErrNotFound) {
		t.Fatalf("missing auth: %v", err)
	}
	// 已撤销
	if _, err := r.RevokeAuthorization(RevokeAuthorizationRequest{
		Operator: "alice", Reason: "改主意", RequestID: "rv1", AuthID: "a1",
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := r.ProxyTransfer(proxyReq("bob", "a1", "x3")); !errors.Is(err, ErrAuthorizationRevoked) {
		t.Fatalf("revoked auth must be rejected distinctly, got %v", err)
	}

	// 已到期：从到期时间点起不可使用
	if _, err := r.CreateAuthorization(createAuthReq(r, "a2", time.Hour)); err != nil {
		t.Fatal(err)
	}
	r.now = func() time.Time { return time.Unix(2_000_000_000, 0) }
	a2, _ := r.GetAuthorization("a2")
	if a2.Status != AuthExpired {
		t.Fatalf("status at/after expiry must be expired, got %s", a2.Status)
	}
	if _, err := r.ProxyTransfer(proxyReq("bob", "a2", "x4")); !errors.Is(err, ErrAuthorizationExpired) {
		t.Fatalf("expired auth must be rejected distinctly, got %v", err)
	}
	r.now = time.Now

	// 已使用
	if _, err := r.CreateAuthorization(createAuthReq(r, "a3", time.Hour)); err != nil {
		t.Fatal(err)
	}
	if _, err := r.ProxyTransfer(proxyReq("bob", "a3", "use1")); err != nil {
		t.Fatal(err)
	}
	if _, err := r.ProxyTransfer(proxyReq("bob", "a3", "x5")); !errors.Is(err, ErrAuthorizationUsed) {
		t.Fatalf("used auth must be rejected distinctly, got %v", err)
	}

	// 任一相关账户停用都拒绝新的代转
	if _, err := r.CreateAuthorization(createAuthReq(r, "a4", time.Hour)); err != nil {
		t.Fatal(err)
	}
	if err := r.DeactivateAccount("alice"); err != nil {
		t.Fatal(err)
	}
	if _, err := r.ProxyTransfer(proxyReq("bob", "a4", "x6")); !errors.Is(err, ErrAccountInactive) {
		t.Fatalf("inactive granter must block proxy, got %v", err)
	}
}

func TestProxyVersionConflictAfterMoveAndReturn(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	r.RegisterAccount("dave", "")
	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}
	// 直接转让使版本变化
	if _, err := r.Transfer(xferReq("alice", "i1", "dave", 1, "d1")); err != nil {
		t.Fatal(err)
	}
	if _, err := r.ProxyTransfer(proxyReq("bob", "a1", "p1")); !errors.Is(err, ErrConflict) {
		t.Fatalf("proxy after version change must conflict, got %v", err)
	}
	// 藏品回到原授权人手中，旧授权仍不能恢复
	if _, err := r.Transfer(xferReq("dave", "i1", "alice", 2, "d2")); err != nil {
		t.Fatal(err)
	}
	if _, err := r.ProxyTransfer(proxyReq("bob", "a1", "p2")); !errors.Is(err, ErrConflict) {
		t.Fatalf("old auth must not revive when item returns, got %v", err)
	}
	h, _ := r.GetHolding("i1")
	if h.OwnerID != "alice" || h.Version != 3 {
		t.Fatalf("rejected proxy must not change holding: %+v", h)
	}
	a, _ := r.GetAuthorization("a1")
	if a.Status != AuthActive {
		t.Fatalf("rejected proxy must leave auth active, got %s", a.Status)
	}
}

// ---- 撤销 ----

func TestRevokeAuthorization(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}

	// 非授权人不能撤销
	if _, err := r.RevokeAuthorization(RevokeAuthorizationRequest{
		Operator: "bob", Reason: "x", RequestID: "rv-bad", AuthID: "a1",
	}); !errors.Is(err, ErrForbidden) {
		t.Fatalf("non-granter revoke must be forbidden, got %v", err)
	}
	// 授权人撤销成功
	res, err := r.RevokeAuthorization(RevokeAuthorizationRequest{
		Operator: "alice", Reason: "改主意", RequestID: "rv1", AuthID: "a1",
	})
	if err != nil || res.Status != AuthRevoked {
		t.Fatalf("revoke: %+v %v", res, err)
	}
	evs, _ := r.AuthorizationHistory("i1")
	if len(evs) != 2 || evs[1].Kind != "revoke" || evs[1].FromStatus != AuthActive ||
		evs[1].ToStatus != AuthRevoked {
		t.Fatalf("revoke event wrong: %+v", evs)
	}
	// 再次撤销不增加记录
	if _, err := r.RevokeAuthorization(RevokeAuthorizationRequest{
		Operator: "alice", Reason: "再撤销", RequestID: "rv2", AuthID: "a1",
	}); err != nil {
		t.Fatalf("re-revoke must succeed: %v", err)
	}
	evs, _ = r.AuthorizationHistory("i1")
	if len(evs) != 2 {
		t.Fatalf("re-revoke must not add event: %d", len(evs))
	}
	// 已使用的授权拒绝撤销
	if _, err := r.CreateAuthorization(createAuthReq(r, "a2", time.Hour)); err != nil {
		t.Fatal(err)
	}
	if _, err := r.ProxyTransfer(proxyReq("bob", "a2", "p1")); err != nil {
		t.Fatal(err)
	}
	if _, err := r.RevokeAuthorization(RevokeAuthorizationRequest{
		Operator: "alice", Reason: "x", RequestID: "rv3", AuthID: "a2",
	}); !errors.Is(err, ErrAuthorizationUsed) {
		t.Fatalf("revoking used auth must fail, got %v", err)
	}
}

// ---- 幂等 ----

func TestAuthorizationRequestIDSharedAcrossKinds(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	// 创建授权占用 "create-a1"，其他操作同号冲突
	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}
	if _, err := r.Transfer(xferReq("alice", "i1", "bob", 1, "create-a1")); !errors.Is(err, ErrRequestConflict) {
		t.Fatalf("request id shared with transfer must conflict, got %v", err)
	}
	if _, err := r.ProxyTransfer(proxyReq("bob", "a1", "create-a1")); !errors.Is(err, ErrRequestConflict) {
		t.Fatalf("request id shared with proxy must conflict, got %v", err)
	}
}

func TestCreateAuthzIdempotency(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	req := createAuthReq(r, "a1", time.Hour)
	r1, err := r.CreateAuthorization(req)
	if err != nil {
		t.Fatal(err)
	}
	r2, err := r.CreateAuthorization(req)
	if err != nil {
		t.Fatalf("replay should succeed: %v", err)
	}
	if !r2.Replayed || r2.GrantVer != r1.GrantVer {
		t.Fatalf("replay mismatch: %+v vs %+v", r1, r2)
	}
	evs, _ := r.AuthorizationHistory("i1")
	if len(evs) != 1 {
		t.Fatalf("duplicate create adds event: %d", len(evs))
	}
	// 业务参数变化 -> 冲突
	req.TrusteeID = "carol"
	if _, err := r.CreateAuthorization(req); !errors.Is(err, ErrRequestConflict) {
		t.Fatalf("changed params must conflict, got %v", err)
	}
}

func TestProxyTransferIdempotentAfterStateChanges(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}
	req := proxyReq("bob", "a1", "p1")
	first, err := r.ProxyTransfer(req)
	if err != nil {
		t.Fatal(err)
	}
	// 成功后代转：藏品再次易手、授权已使用、账户停用、时间越过到期点
	if _, err := r.Transfer(xferReq("carol", "i1", "bob", 2, "t2")); err != nil {
		t.Fatal(err)
	}
	if err := r.DeactivateAccount("alice"); err != nil {
		t.Fatal(err)
	}
	r.now = func() time.Time { return time.Unix(3_000_000_000, 0) }
	again, err := r.ProxyTransfer(req)
	if err != nil {
		t.Fatalf("successful proxy must replay despite later state changes: %v", err)
	}
	if !again.Replayed || again.TxSeq != first.TxSeq || again.Version != 2 ||
		again.ToID != "carol" || again.FromID != "alice" {
		t.Fatalf("replayed proxy != first: %+v vs %+v", again, first)
	}
	hist, _ := r.History("i1")
	if len(hist) != 3 { // issue + proxy + later direct transfer
		t.Fatalf("replay adds no history: %d", len(hist))
	}
	h, _ := r.GetHolding("i1")
	if h.OwnerID != "bob" || h.Version != 3 {
		t.Fatalf("replay must not change holding: %+v", h)
	}
}

func TestProxyRejectedRequestReplaysRejection(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	// 授权很快到期；首次代转在到期后被拒（状态类拒绝，占用请求号）
	req := createAuthReq(r, "a1", time.Minute)
	if _, err := r.CreateAuthorization(req); err != nil {
		t.Fatal(err)
	}
	r.now = func() time.Time { return req.ExpiresAt.Add(time.Second) }
	preq := proxyReq("bob", "a1", "late")
	if _, err := r.ProxyTransfer(preq); !errors.Is(err, ErrAuthorizationExpired) {
		t.Fatalf("first proxy should be expired, got %v", err)
	}
	// 即使授权被撤销（另一个拒绝原因），原请求重放仍返回首次拒绝
	if _, err := r.RevokeAuthorization(RevokeAuthorizationRequest{
		Operator: "alice", Reason: "x", RequestID: "rv", AuthID: "a1",
	}); err != nil {
		t.Fatal(err)
	}
	res, err := r.ProxyTransfer(preq)
	if !errors.Is(err, ErrAuthorizationExpired) || !res.Replayed {
		t.Fatalf("must replay first rejection: res=%+v err=%v", res, err)
	}
}

func TestNotFoundDoesNotConsumeRequestID(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	// 引用不存在的授权发起代转不占用请求号
	preq := proxyReq("bob", "ghost", "p1")
	if _, err := r.ProxyTransfer(preq); !errors.Is(err, ErrNotFound) {
		t.Fatal(err)
	}
	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}
	// 之后授权存在时该请求号应仍可用
	if _, err := r.ProxyTransfer(proxyReq("bob", "a1", "p1")); err != nil {
		t.Fatalf("request id must remain usable after not-found rejection: %v", err)
	}
}

// ---- 并发：直接转让与代转争用同一版本 ----

func TestConcurrentProxyVsDirectSameVersion(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}
	r.RegisterAccount("dave", "")

	const n = 16
	var wg sync.WaitGroup
	errs := make([]error, n)
	wg.Add(n)
	for i := 0; i < n; i++ {
		i := i
		go func() {
			defer wg.Done()
			if i%2 == 0 {
				_, errs[i] = r.ProxyTransfer(proxyReq("bob", "a1", fmt.Sprintf("p%d", i)))
			} else {
				_, errs[i] = r.Transfer(xferReq("alice", "i1", "dave", 1, fmt.Sprintf("d%d", i)))
			}
		}()
	}
	wg.Wait()
	succ := 0
	for _, e := range errs {
		if e == nil {
			succ++
		}
	}
	if succ != 1 {
		t.Fatalf("exactly one of direct/proxy must succeed, got %d", succ)
	}
	h, _ := r.GetHolding("i1")
	if h.Version != 2 {
		t.Fatalf("version must be 2, got %d", h.Version)
	}
	hist, _ := r.History("i1")
	if len(hist) != 2 {
		t.Fatalf("exactly one transfer history, got %d", len(hist))
	}
	// 成功的若是代转，持有人必须是授权指定的 carol；若是直接转让，则是 dave
	if hist[1].AuthID == "a1" && h.OwnerID != "carol" {
		t.Fatalf("proxy winner must send to fixed receiver, got %s", h.OwnerID)
	}
}

// 撤销与代转同时发生：存在完整先后次序，撤销先则代转被拒，代转先则
// 授权已使用、撤销被拒。
func TestConcurrentRevokeVsProxy(t *testing.T) {
	for range 20 {
		r := mustCreate(t, filepath.Join(t.TempDir(), "d"))
		authzWorld(t, r)
		if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
			t.Fatal(err)
		}
		var wg sync.WaitGroup
		var proxyErr, revokeErr error
		wg.Add(2)
		go func() {
			defer wg.Done()
			_, proxyErr = r.ProxyTransfer(proxyReq("bob", "a1", "p1"))
		}()
		go func() {
			defer wg.Done()
			_, revokeErr = r.RevokeAuthorization(RevokeAuthorizationRequest{
				Operator: "alice", Reason: "争用", RequestID: "rv1", AuthID: "a1",
			})
		}()
		wg.Wait()
		h, _ := r.GetHolding("i1")
		a, _ := r.GetAuthorization("a1")
		switch {
		case proxyErr == nil:
			if revokeErr == nil || !errors.Is(revokeErr, ErrAuthorizationUsed) {
				t.Fatalf("proxy-first must make revoke fail with used, got %v", revokeErr)
			}
			if h.OwnerID != "carol" || h.Version != 2 || a.Status != AuthUsed {
				t.Fatalf("proxy-first state wrong: %+v auth=%s", h, a.Status)
			}
		case errors.Is(proxyErr, ErrAuthorizationRevoked):
			if revokeErr != nil {
				t.Fatalf("revoke-first must succeed, got %v", revokeErr)
			}
			if h.OwnerID != "alice" || h.Version != 1 || a.Status != AuthRevoked {
				t.Fatalf("revoke-first state wrong: %+v auth=%s", h, a.Status)
			}
		default:
			t.Fatalf("unexpected ordering: proxy=%v revoke=%v", proxyErr, revokeErr)
		}
	}
}

// 停用与代转同时发生。
func TestConcurrentDeactivateVsProxy(t *testing.T) {
	for range 20 {
		r := mustCreate(t, filepath.Join(t.TempDir(), "d"))
		authzWorld(t, r)
		if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
			t.Fatal(err)
		}
		var wg sync.WaitGroup
		var proxyErr, deactErr error
		wg.Add(2)
		go func() {
			defer wg.Done()
			_, proxyErr = r.ProxyTransfer(proxyReq("bob", "a1", "p1"))
		}()
		go func() {
			defer wg.Done()
			deactErr = r.DeactivateAccount("carol")
		}()
		wg.Wait()
		if deactErr != nil {
			t.Fatalf("deactivate: %v", deactErr)
		}
		h, _ := r.GetHolding("i1")
		hist, _ := r.History("i1")
		if proxyErr == nil {
			if h.OwnerID != "carol" || h.Version != 2 || len(hist) != 2 {
				t.Fatalf("proxy-first state wrong: %+v hist=%d", h, len(hist))
			}
		} else {
			if !errors.Is(proxyErr, ErrAccountInactive) {
				t.Fatalf("deactivate-first proxy must be inactive-rejected, got %v", proxyErr)
			}
			if h.OwnerID != "alice" || h.Version != 1 || len(hist) != 1 {
				t.Fatalf("deactivate-first state wrong: %+v hist=%d", h, len(hist))
			}
		}
	}
}

// ---- 到期边界 ----

func TestExpiryBoundary(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	base := time.Unix(1_700_000_000, 0)
	r.now = func() time.Time { return base }

	req := createAuthReq(r, "a1", time.Hour)
	req.ExpiresAt = base.Add(time.Hour)
	if _, err := r.CreateAuthorization(req); err != nil {
		t.Fatal(err)
	}
	// 到期前一刻可用
	r.now = func() time.Time { return base.Add(time.Hour - time.Nanosecond) }
	if a, _ := r.GetAuthorization("a1"); a.Status != AuthActive {
		t.Fatalf("just before expiry must be active, got %s", a.Status)
	}
	// 正好到期时间点起不可使用
	r.now = func() time.Time { return base.Add(time.Hour) }
	if a, _ := r.GetAuthorization("a1"); a.Status != AuthExpired {
		t.Fatalf("at expiry must be expired, got %s", a.Status)
	}
	if _, err := r.ProxyTransfer(proxyReq("bob", "a1", "p1")); !errors.Is(err, ErrAuthorizationExpired) {
		t.Fatalf("proxy at expiry must fail expired, got %v", err)
	}
}

// ---- 持久化 ----

func TestAuthorizationPersistenceAcrossReopen(t *testing.T) {
	dir := tempDir(t)
	r := mustCreate(t, dir)
	authzWorld(t, r)
	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", 24*time.Hour)); err != nil {
		t.Fatal(err)
	}
	if _, err := r.ProxyTransfer(proxyReq("bob", "a1", "p1")); err != nil {
		t.Fatal(err)
	}
	if _, err := r.CreateAuthorization(createAuthReq(r, "a2", time.Hour)); err != nil {
		t.Fatal(err)
	}
	if _, err := r.RevokeAuthorization(RevokeAuthorizationRequest{
		Operator: "alice", Reason: "撤销", RequestID: "rv1", AuthID: "a2",
	}); err != nil {
		t.Fatal(err)
	}
	if err := r.Close(); err != nil {
		t.Fatal(err)
	}

	r2, err := Open(dir)
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	defer r2.Close()

	a1, err := r2.GetAuthorization("a1")
	if err != nil || a1.Status != AuthUsed || a1.UsedTxSeq != 2 {
		t.Fatalf("used auth must persist: %+v %v", a1, err)
	}
	a2, err := r2.GetAuthorization("a2")
	if err != nil || a2.Status != AuthRevoked {
		t.Fatalf("revoked auth must persist: %+v %v", a2, err)
	}
	evs, err := r2.AuthorizationHistory("i1")
	if err != nil || len(evs) != 4 {
		t.Fatalf("auth events must persist: %d %v", len(evs), err)
	}
	hist, err := r2.History("i1")
	if err != nil || len(hist) != 2 || hist[1].AuthID != "a1" || hist[1].Operator != "bob" {
		t.Fatalf("proxy history must persist with trustee and auth trace: %+v %v", hist, err)
	}
	// 成功代转请求号重放
	again, err := r2.ProxyTransfer(proxyReq("bob", "a1", "p1"))
	if err != nil || !again.Replayed || again.TxSeq != 2 {
		t.Fatalf("proxy replay across reopen: %+v %v", again, err)
	}
	// 已撤销授权重开后代转仍被拒
	if _, err := r2.ProxyTransfer(proxyReq("bob", "a2", "p2")); !errors.Is(err, ErrAuthorizationRevoked) {
		t.Fatalf("revoked auth still rejects after reopen: %v", err)
	}
}

// 旧版本写出的数据（没有授权字段）必须能直接打开，原历史不变。
func TestOpenSnapshotWithoutAuthorizationFields(t *testing.T) {
	dir := tempDir(t)
	r := mustCreate(t, dir)
	setupWorld(t, r)
	if _, err := r.Issue(issueReq("i1", "alice")); err != nil {
		t.Fatal(err)
	}
	if _, err := r.Transfer(xferReq("alice", "i1", "bob", 1, "t1")); err != nil {
		t.Fatal(err)
	}
	if err := r.Close(); err != nil {
		t.Fatal(err)
	}

	// 读入旧格式快照（删除新字段后即为旧格式），确认仍可打开。
	b, err := readDataFile(dir)
	if err != nil {
		t.Fatal(err)
	}
	for _, key := range []string{`"authzs"`, `"auth_events"`, `"next_auth_seq"`, `"auth_id"`} {
		if contains(string(b), key) {
			t.Fatalf("baseline snapshot should not contain %s", key)
		}
	}
	r2, err := Open(dir)
	if err != nil {
		t.Fatalf("old snapshot must open: %v", err)
	}
	defer r2.Close()
	hist, _ := r2.History("i1")
	if len(hist) != 2 || hist[1].AuthID != "" {
		t.Fatalf("original history unchanged: %+v", hist)
	}
	if evs, err := r2.AuthorizationHistory("i1"); err != nil || len(evs) != 0 {
		t.Fatalf("old item has empty auth history: %v %v", evs, err)
	}
	// 打开后新功能可正常使用
	if _, err := r2.CreateAuthorization(createAuthReq(r2, "a1", time.Hour)); err != nil {
		t.Fatalf("new feature works on opened old registry: %v", err)
	}
}

