547	// ---- 限时一次性代转授权 ----
548	
549	// authzCurrentStatus 计算授权当前状态。撤销与使用是落盘的终态；到期不
550	// 落盘，按当前时间实时判断——从到期时间点起即视为已过期。
551	func authzCurrentStatus(a authzRec, now time.Time) string {
552		switch a.Status {
553		case "revoked":
554			return AuthRevoked
555		case "used":
556			return AuthUsed
557		}
558		if !a.ExpiresAt.IsZero() && !now.Before(a.ExpiresAt) {
559			return AuthExpired
560		}
561		return AuthActive
562	}
563	
564	func (req CreateAuthorizationRequest) validatePresent() error {
565		missing := []string{}
566		if strings.TrimSpace(req.Operator) == "" {
567			missing = append(missing, "operator")
568		}
569		if strings.TrimSpace(req.Reason) == "" {
570			missing = append(missing, "reason")
571		}
572		if strings.TrimSpace(req.RequestID) == "" {
573			missing = append(missing, "request_id")
574		}
575		if strings.TrimSpace(req.AuthID) == "" {
576			missing = append(missing, "auth_id")
577		}
578		if strings.TrimSpace(req.ItemID) == "" {
579			missing = append(missing, "item_id")
580		}
581		if strings.TrimSpace(req.TrusteeID) == "" {
582			missing = append(missing, "trustee_id")
583		}
584		if strings.TrimSpace(req.ToID) == "" {
585			missing = append(missing, "to_id")
586		}
587		if strings.TrimSpace(req.ExpectedOwner) == "" {
588			missing = append(missing, "expected_owner")
589		}
590		if req.ExpectedVer <= 0 {
591			missing = append(missing, "expected_version")
592		}
593		if req.ExpiresAt.IsZero() {
594			missing = append(missing, "expires_at")
595		}
596		if len(missing) > 0 {
597			return fmt.Errorf("%w: 创建授权请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
598		}
599		return nil
600	}
601	
